'use strict';
const E=ScoreEngine,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const fmt=v=>v===null||v===undefined?'—':Number(v).toFixed(2);
const fmtRatio=v=>E.blank(v)?'':Number((Number(v)*100).toFixed(4));
const fmtPercent=v=>Number((v*100).toFixed(4))+'%';
const uid=()=>crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
const ruleMap=new Map(RULES.obs.map(o=>[o.id,o]));
const stamp=()=>new Date().toLocaleString('zh-CN',{hour12:false});
let viewSort='default',rosterSelection='';
function sortView(rows,order=viewSort){return [...rows].sort((a,b)=>order==='id'?a.id.localeCompare(b.id,undefined,{numeric:true}):order==='name'?a.name.localeCompare(b.name,'zh-CN'):order==='score'?((result(b).total??-Infinity)-(result(a).total??-Infinity)||a.id.localeCompare(b.id)):0);}
let project={format:E.VERSION,title:'我的评定班级',config:E.defaults(),students:[],modified:stamp(),serial:0},db,cache=new Map(),page='overview',selected='',tab='required',dimension='政治思想',query='',filter='all',overviewPage=0,rosterPage=0,readOnly=false,saving=false,saveAgain=false,dirty=false,undoStack=[],lastBackupSerial=-1,bulkMode='roster',previewData=null,renderTimer,toastTimer,releaseLock,loadFailure=false,rawStored=null,initialized=false;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function reportError(error){console.error(error);toast(error.message||String(error));}
function saveLabel(message,error=false){$('#saveState').textContent=message;$('#saveState').className=error?'error':'';}
function recalc(s){cache.set(s.id,E.calculate(s,project.config,RULES));return cache.get(s.id);}
function recalcAll(){cache=new Map(project.students.map(s=>[s.id,E.calculate(s,project.config,RULES)]));}
const current=()=>project.students.find(s=>s.id===selected);
const result=s=>cache.get(s.id)||recalc(s);
function badge(status){const color={'待补齐':'amber','输入异常':'red','待处理':'amber','待学生核对':'blue','待老师核对':'blue','待复核':'blue','已复核':'green'}[status]||'';return `<span class="badge ${color}">${esc(status)}</span>`;}
function chooseOptions(options,value,placeholder='请选择'){return `<option value="">${placeholder}</option>`+options.map(o=>{const pair=Array.isArray(o)?o:[o,o];return `<option value="${esc(pair[0])}" ${String(value??'')===String(pair[0])?'selected':''}>${esc(pair[1])}</option>`;}).join('');}
function guard(){if(!initialized){toast('正在读取本机数据，请稍候。');return false;}if(readOnly||loadFailure){toast(loadFailure?'本地数据未能打开，请先导出抢救备份或重新打开。':'另一个窗口正在编辑，请关闭另一个窗口后重新打开。');return false;}return true;}
function checkpoint(label,student=null){undoStack.push(student?{label,studentId:student.id,before:clone(student)}:{label,data:clone(project)});const entry=undoStack.at(-1);entry.bytes=JSON.stringify(entry).length*2;while(undoStack.length>15||undoStack.length>1&&undoStack.reduce((n,x)=>n+(x.bytes||0),0)>24*1024*1024)undoStack.shift();}
function touch(s){s.revision++;s.confirmation=null;s.approval=null;s.updated=stamp();}
function modified(label='修改数据'){project.modified=stamp();project.serial++;dirty=true;saveLabel('正在保存…');void save();}
function mutate(label,fn,{all=false,refresh=true,student=current()}={}){if(!guard())return;checkpoint(label,student);fn();if(student)touch(student);if(all)recalcAll();else if(student)recalc(student);modified(label);if(refresh)render();}
function undoLastChange(){if(!guard()||!undoStack.length)return;const prev=undoStack.pop(),serial=project.serial;let name='';if(prev.before){const idx=project.students.findIndex(s=>s.id===prev.studentId);if(idx>=0){project.students[idx]=prev.before;name=String(prev.label).includes(prev.before.name)?'':prev.before.name+' / ';}}else{project=prev.data;project.serial=serial;}recalcAll();modified('撤销：'+prev.label);render();toast('已撤销：'+name+prev.label);}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('BUPTStandaloneScores',1);r.onupgradeneeded=()=>{r.result.createObjectStore('workspace');r.result.createObjectStore('history',{keyPath:'key'});};r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result);r.onblocked=()=>reject(Error('请先关闭其他综测窗口。'));});}
function readStore(store,key){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readonly'),r=t.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function save(){
 if(saving){saveAgain=true;return;}if(!db||readOnly||loadFailure)return;
 saving=true;let snapshot=clone(project),serial=snapshot.serial;
 try{await new Promise((resolve,reject)=>{const t=db.transaction(['workspace','history'],'readwrite'),h=t.objectStore('history');t.objectStore('workspace').put(snapshot,'current');h.put({key:serial%6,serial,time:snapshot.modified,data:snapshot});t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('保存事务中断'));});if(project.serial===serial){dirty=false;saveLabel('✓ 已保存到本机');}}
 catch(err){dirty=true;saveLabel('保存失败 · 请立即备份',true);toast('本机保存失败。请点击“备份数据”保存 JSON 文件。');console.error(err);}
 finally{saving=false;if(saveAgain||project.serial!==serial){saveAgain=false;void save();}}
}
async function settled(){for(let i=0;i<100&&saving;i++)await new Promise(r=>setTimeout(r,30));if(dirty)throw Error('本机保存尚未成功，请先下载备份。');}
function ruleLabel(){$('#ruleBadge').textContent=project.config.confirmed?`${project.config.year} · ${project.config.cohort} · 规则已确认`:'试算中 · 规则待确认';}
function selectedList(){return sortView(project.students.filter(s=>{const r=result(s);return (!query||[s.id,s.name,s.group].some(v=>v.toLowerCase().includes(query.toLowerCase())))&&(filter==='all'||filter==='missing'&&r.total===null||filter==='pending'&&!r.approved||filter==='approved'&&r.approved||filter==='ready'&&r.ready&&!r.approved||filter==='work'&&r.total!==null&&!r.ready); }));}
function appNav(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));ruleLabel();}
function render(){appNav();if(page==='overview')renderOverview();else renderWorkspace();}
function emptyView(){return `<main><section class="panel empty"><div class="big-icon">▦</div><div class="eyebrow">NO EXCEL. NO INSTALLATION.</div><h1>把名单放进来，剩下的交给应用。</h1><p>导入名单、录入数据、老师核对，三步完成。<br>最多 500 名学生；无网络也能用，不需要启用宏。</p><div class="actions" style="justify-content:center;margin-top:25px"><button class="primary" data-action="bulk">导入学生名单</button><button data-action="settings">先确认学年与规则</button><button data-action="restore">从 JSON 备份恢复</button><button data-action="demo">先试用 10 名示例学生</button></div></section><div class="steps"><div class="step"><i>01 / 建名单</i><h3>从 Excel 复制，直接粘贴</h3><p class="hint">只需学号、姓名、班级三列。按学号匹配，排序不影响数据。</p></div><div class="step"><i>02 / 填成绩与奖项</i><h3>选等级，填次数，分数自动算</h3><p class="hint">只展开有内容的观测点；没有参加的项目不用填。</p></div><div class="step"><i>03 / 核对与导出</i><h3>有问题直接定位，不在表里找</h3><p class="hint">逐人打印核对单，汇总可导出 CSV。JSON 备份可恢复全部数据。</p></div></div><div class="small-actions" style="margin-top:22px"><button data-action="undo" ${undoStack.length?'':'disabled'}>撤销上一步</button><button data-action="history">恢复最近自动存档</button></div><p class="hint">数据保存在当前浏览器的本机空间。换电脑或清理浏览器前，请下载备份；应用文件本身不包含你录入的数据。</p></main>`;}
function renderOverview(){
 if(!project.students.length){$('#app').innerHTML=emptyView();return;}
 const rs=project.students.map(result),complete=rs.filter(r=>r.total!==null),approved=rs.filter(r=>r.approved).length,avg=complete.length?complete.reduce((a,r)=>a+r.total,0)/complete.length:null;
 $('#app').innerHTML=`<main><div class="heading"><div><div class="eyebrow">CLASS WORKSPACE / 本地工作区</div><h1>${esc(project.title)}</h1><div class="subtle">先导入名单，再到统一录入页面填成绩和活动，最后由老师核对并导出。</div></div><div class="actions"><button data-simple="roster">名单管理</button><button class="primary" data-action="export">导出结果</button></div></div><div class="stats"><div class="stat accent"><span>学生总数 / 容量 500 人</span><b>${project.students.length}<small>人</small></b></div><div class="stat"><span>已生成试算</span><b>${complete.length}<small>/ ${project.students.length}</small></b></div><div class="stat"><span>老师已核对</span><b>${approved}<small>人</small></b></div><div class="stat"><span>已补齐学生的试算均分</span><b>${fmt(avg)}</b></div></div>${!project.config.confirmed?'<div class="note amber">当前为试算。正式复核前，请在“其他功能 → 评定规则”确认学年、适用年级及规则口径。 <button class="linkish" data-action="settings">去设置 →</button></div>':''}<section class="panel"><div class="toolbar"><div><h2 style="margin:0">学生进度</h2><span class="hint">按学号关联，放心排序</span></div><div><button data-page="gradegrid">进入数据录入 →</button></div></div><div class="toolbar"><div><input id="search" aria-label="搜索学生" placeholder="搜索姓名 / 学号 / 班级" value="${esc(query)}"><select id="statusFilter" aria-label="筛选状态">${chooseOptions([['all','全部学生'],['missing','缺失 / 输入异常'],['pending','尚未复核'],['work','待处理（材料 / 资格）'],['ready','待老师核对（已就绪）'],['approved','已复核']],filter,'筛选')}</select></div><div><button data-action="sortId" class="plain">按学号排序</button><button data-action="sortDefault" class="plain">原名单顺序</button><button data-action="sortName" class="plain">按姓名排序</button><button data-action="sortScore" class="plain">按分数排序</button></div></div><div id="overviewTable"></div></section><div class="small-actions"><button data-action="undo" ${undoStack.length?'':'disabled'}>撤销上一步</button></div><p class="hint">${esc(project.modified)} 更新 · 学生数据保存在本机；仅在授权使用 AI 时发送选定资料 · 已补齐不等于已复核，正式名单以“已复核”为准。</p></main>`;
 renderOverviewTable();
}
function renderOverviewTable(){const rows=selectedList(),pages=Math.max(1,Math.ceil(rows.length/50));overviewPage=Math.min(overviewPage,pages-1);$('#overviewTable').innerHTML=`<div class="table-wrap"><table><thead><tr><th>姓名 / 学号</th><th>班级</th><th class="num">基本</th><th class="num">专业</th><th class="num">发展</th><th class="num">试算总分</th><th>当前进度</th><th>操作</th></tr></thead><tbody>${rows.slice(overviewPage*50,overviewPage*50+50).map(s=>{const r=result(s);return `<tr data-student="${esc(s.id)}"><td><b>${esc(s.name)}</b><div class="hint">${esc(s.id)}</div></td><td>${esc(s.group)}</td><td class="num">${fmt(r.basic)}</td><td class="num">${fmt(r.professional)}</td><td class="num">${fmt(r.development)}</td><td class="num"><strong>${fmt(r.total)}</strong></td><td>${badge(r.status)}</td><td><a>查看 / 录入 →</a></td></tr>`;}).join('')||'<tr><td colspan="8">没有符合条件的学生</td></tr>'}</tbody></table></div><div class="pagination"><span>找到 ${rows.length} 人，每页最多显示 50 人</span><div><button data-action="prevTable" ${overviewPage===0?'disabled':''}>上一页</button><span>${overviewPage+1} / ${pages}</span><button data-action="nextTable" ${overviewPage>=pages-1?'disabled':''}>下一页</button></div></div>`;}
function renderWorkspace(){
 if(!project.students.length){$('#app').innerHTML=emptyView();return;}
 if(!current())selected=project.students[0].id;
 $('#app').innerHTML=`<div class="workspace"><aside class="roster"><div class="roster-top"><strong>学生名单 <span class="hint">${project.students.length} 人</span></strong><input id="search" aria-label="搜索学生" placeholder="姓名 / 学号 / 班级" value="${esc(query)}"><select id="statusFilter" aria-label="筛选状态">${chooseOptions([['all','全部学生'],['missing','缺失 / 输入异常'],['pending','尚未复核'],['work','待处理（材料 / 资格）'],['ready','待老师核对（已就绪）'],['approved','已复核']],filter)}</select></div><div class="roster-list" id="rosterList"></div><div class="roster-foot" id="rosterFoot"></div></aside><section class="editor" id="editor"></section></div>`;
 renderRoster();renderEditor();
}
function renderRoster(){const rows=selectedList();if(rosterSelection!==selected){const index=rows.findIndex(s=>s.id===selected);if(index>=0)rosterPage=Math.floor(index/60);rosterSelection=selected;}const pages=Math.max(1,Math.ceil(rows.length/60));rosterPage=Math.min(rosterPage,pages-1);$('#rosterList').innerHTML=rows.slice(rosterPage*60,rosterPage*60+60).map(s=>{const r=result(s);return `<button class="student-btn ${s.id===selected?'active':''}" data-student="${esc(s.id)}"><span><b>${esc(s.name)}</b><small>${esc(s.id)} · ${esc(s.group)}</small></span><span><b>${fmt(r.total)}</b><small>${esc(r.status)}</small></span><i class="dot ${r.approved?'good':r.total===null?'err':r.ready?'ready':'warn'}"></i></button>`;}).join('')||'<p class="hint">没有符合条件的学生</p>';$('#rosterFoot').innerHTML=`${rows.length} 人 · 第 ${rosterPage+1}/${pages} 页 <button class="plain" data-action="prevRoster" ${rosterPage===0?'disabled':''}>‹</button><button class="plain" data-action="nextRoster" ${rosterPage>=pages-1?'disabled':''}>›</button>`;}
function stripHTML(s){const r=result(s);return `<div class="score-strip"><div class="total"><span>综合成绩 · ${r.approved?'已复核':'试算'}</span><b>${fmt(r.total)}</b></div><div><span>基本素质 × ${fmtPercent(project.config.weights[0])}</span><b>${fmt(r.basic)}</b></div><div><span>专业素质 × ${fmtPercent(project.config.weights[1])}</span><b>${fmt(r.professional)}</b></div><div><span>发展素质 × ${fmtPercent(project.config.weights[2])}</span><b>${fmt(r.development)}</b></div></div>`;}
function renderEditor(){const s=current(),r=result(s);$('#editor').innerHTML=`<div class="student-head"><div><div class="eyebrow">STUDENT RECORD / 个人记录</div><h1>${esc(s.name)} <span id="studentBadge">${badge(r.status)}</span></h1><div class="subtle">${esc(s.id)}　·　${esc(s.group)} <button class="linkish" data-action="editStudent">编辑</button></div></div><div class="actions"><button data-action="printOne">打印核对单</button><button data-action="nextStudent">下一位 →</button></div></div><div id="scoreStrip">${stripHTML(s)}</div><div class="tabs" role="tablist">${[['required','个人成绩'],['activities','活动与奖项'],['review','老师核对']].map(([v,t])=>`<button role="tab" aria-selected="${v===tab}" class="${v===tab?'active':''}" data-tab="${v}">${t}</button>`).join('')}</div><div id="tabBody">${tab==='required'?requiredHTML(s):tab==='activities'?activitiesHTML(s):reviewHTML(s)}</div><div class="footer-actions"><div><button data-action="undo" ${undoStack.length?'':'disabled'}>撤销上一步</button></div><button class="primary" data-action="${tab==='required'?'toActivities':tab==='activities'?'toReview':'nextStudent'}">${tab==='required'?'下一步：活动与奖项 →':tab==='activities'?'下一步：老师核对 →':'下一位学生 →'}</button></div>`;}
function fieldHTML(label,value,attr='',{type='number',min=0,max=100,step='any',placeholder='未填写'}={}){return `<label>${label}<input type="${type}" value="${esc(value)}" ${attr} ${type==='number'?`min="${min}" max="${max}" step="${step}" ${step===1?'list="countChoices"':''}`:''} placeholder="${esc(placeholder)}"></label>`;}
function requiredHTML(s){return `<div class="note">仅需补齐下面的 13 项原始成绩。真实 0 分请填 <b>0</b>，缺失请留空；无需录入没有参加的活动。</div><section class="panel"><div class="toolbar" style="margin-top:0"><h2 style="margin:0">教务与体育成绩</h2><button data-page="gradegrid" class="plain">返回全班成绩表 →</button></div><div class="form-grid">${fieldHTML('专业素质成绩（0–100）',s.professional,'data-professional')}${fieldHTML('体质健康测试（0–100）',s.values.D024?.[0],'data-value="D024" data-index="0"')}${fieldHTML('耐力跑 / 体育锻炼（0–100）',s.values.D025?.[0],'data-value="D025" data-index="0"')}</div></section><section class="panel"><h2>五个维度的班级评议</h2><div class="hint">互评 ${fmtPercent(project.config.peer)} ＋ 辅导员 / 班主任 ${fmtPercent(project.config.counselor)}。由实际评议结果计算，不自动赠满分。</div><div class="review-grid header"><span>评价维度 / 单项上限</span><span>同学互评</span><span>辅导员 / 班主任</span></div>${RULES.obs.filter(o=>o.type==='base').map(o=>`<div class="review-grid"><span>${o.dim} <span class="hint">/ ${o.max}</span></span>${[0,1].map(i=>`<input aria-label="${o.dim}${i?'辅导员评议':'互评'}" type="number" min="0" max="${o.max}" step="any" placeholder="未填写" value="${esc(s.values[o.id]?.[i])}" data-value="${o.id}" data-index="${i}">`).join('')}</div>`).join('')}</section><div id="requiredIssues">${issuesHTML(result(s).issues.filter(i=>['professional',...RULES.obs.filter(o=>['base','external'].includes(o.type)).map(o=>o.id)].includes(i.id)))}</div>`;}
function issuesHTML(issues){return issues.length?`<div class="note amber"><b>还需要处理 ${issues.length} 项</b>${issues.slice(0,30).map(i=>`<button class="notice-link" data-locate="${esc(i.id)}">${esc(i.message)} →</button>`).join('')}${issues.length>30?'<div>其余问题请依次处理。</div>':''}</div>`:'<div class="note">✓ 本页没有缺失或异常。</div>';}
function ruleHint(o){if(o.type==='activity')return `市级以上 2 分/次，校院级 1 分/次${o.cap!==null?'，年级班级 0.5 分/次（这一档最高 '+o.cap+' 分）':''}${o.audience?'；观众按相应档次的 30% 计分':''}。`;
 if(o.type==='hours')return '每满 10 小时 0.5 分，最高 5 分；不足 10 小时不计。';
 if(o.type==='qty')return `${o.rate} 分/次；未填写为 0 次。`;
 if(o.type==='bool')return `符合资格计 ${o.rate} 分，否则为 0。`;
 if(o.type==='job')return '同一任职序列取最高，任期半年按 50%，不足半年不计。其他不同序列填写审核后已折算的分数（0–8）。';
 if(o.type==='discipline')return project.config.discipline==='fixed'?'按量化参考固定值扣分。':'按办法区间认定：警告 30–40、严重警告 40–50、记过 50–60、留校察看 60–100、治安处罚 100。';
 return `${o.sign<0?'本项为扣分。':''}${o.team?`团队人数 1–${o.team}，个人选 1；${o.collective?'比例留空为均分，填写比例后个人不超过原奖分。':'按 (1＋0.6×(人数−1)) / 人数折算。'}`:''}${o.cap!==null?'本观测点合计最高 '+o.cap+' 分。':''}${o.condition||''}${o.transfer?'职业大赛超过职业 4 分的部分转入科学创新。':''}`||'选择已认定的等级，填写次数；同一事项多级获奖只保留最高项。';}
function activitiesHTML(s){const dims=RULES.dims;const d=dims.find(d=>d.name===dimension)||dims[0];dimension=d.name;const r=result(s);return `<div class="toolbar" style="margin-top:0"><div class="actions"><button data-activity-module="基本" class="${d.module==='基本'?'primary':''}">基本素质</button><button data-activity-module="发展" class="${d.module==='发展'?'primary':''}">发展素质</button></div><input id="observationSearch" aria-label="查找观测点" placeholder="查找项目：志愿 / 竞赛 / 证书…"></div><div id="observationMatches" class="small-actions"></div><div class="dimension-nav">${dims.filter(item=>item.module===d.module).map(d=>`<button data-dimension="${d.name}" class="${d.name===dimension?'active':''}">${d.name} <small>${fmt(r.dimensions[d.name])}</small></button>`).join('')}</div><div class="toolbar"><div><h2 style="margin:0">${dimension}</h2><span class="hint">${d.module}素质 · ${dimension==='整体扣分'?'在基本素质汇总后扣减':'维度上限 '+d.max+' 分'}</span></div><label class="check"><input type="checkbox" id="onlyFilled">仅看已填写项目</label></div><div class="hint" style="margin-bottom:15px">未参加的项目留空即为 0。点开项目即可填；同一观测点可以追加多条奖项。</div>${d.items.filter(o=>!['base','external'].includes(o.type)).map(o=>observationHTML(s,ruleMap.get(o.id))).join('')}`;}
function observationHTML(s,o){const r=result(s),v=s.values[o.id]||[],aw=s.awards[o.id]||[],filled=v.some(x=>!E.blank(x))||aw.length>0;return `<details class="observation" id="obs-${o.id}" data-filled="${filled}" ${filled?'open':''}><summary class="obs-head"><span class="obs-title"><span class="code">${o.id}</span>${o.name}</span><span data-observation-status>${(r.details[o.id]||[]).some(d=>d.missing?.length&&d.status!=='不计分')?'<span class="badge amber">待填写</span>':aw.some(a=>a.status==='待审核')?'<span class="badge amber">待审核</span>':''}</span>${o.sign<0?'<span class="badge red">扣分</span>':''}<strong>${r.points[o.id]===null?'待处理':(o.sign<0?'−':'')+fmt(r.points[o.id])}</strong></summary><div class="obs-body"><div class="hint">${ruleHint(o)} <span>依据：量化参考第 ${o.page} 页。</span></div>${['award','range','discipline'].includes(o.type)?`${aw.map((a,i)=>awardHTML(o,a,i,r.details[o.id]?.[i])).join('')}<button data-add-award="${o.id}" style="margin-top:12px">＋ 添加一条${o.type==='discipline'?'处分':o.sign<0?'扣分记录':'奖项 / 认定分'}</button>`:`<div class="fields" style="margin-top:15px">${o.fields.map((f,i)=>{const at=`data-value="${o.id}" data-index="${i}"`;if(['bool','option','tenure'].includes(f.kind)){const options=f.kind==='bool'?['是','否']:f.kind==='tenure'?['不足半年','半年','超过半年']:o.options.map(p=>[p[0],p[0]+'（'+p[1]+'分）']);return `<label>${esc(f.label)}<select ${at}>${chooseOptions(options,v[i],f.kind==='bool'?'没有 / 不填':'请选择')}</select></label>`;}return fieldHTML(esc(f.label),v[i],at,{min:f.lo,max:f.kind==='count'?999999:f.hi,step:f.kind==='count'?1:'any',placeholder:'未填为 0'});}).join('')}</div>`}<div class="obs-feedback">${r.issues.filter(i=>i.id===o.id).map(i=>`<div class="note red">${esc(i.message)}</div>`).join('')}</div></div></details>`;}
function awardHTML(o,a,i,detail){const at=k=>`data-award="${o.id}" data-row="${i}" data-key="${k}"`;return `<div class="award-row"><div class="award-title"><span data-record-value="${i}">${esc(awardCaption(a,i,detail))}</span><button class="plain danger" data-delete-award="${o.id}" data-row="${i}">移除</button></div><div class="fields"><label class="wide">${o.type==='discipline'?'处分类型':'奖次 / 审核认定分'}<select ${at('option')}>${chooseOptions(o.options.map(([k,v])=>[k,k+'（'+v+'分）']),a.option)}</select></label>${fieldHTML('次数',a.count,at('count'),{min:0,max:999999,step:1,placeholder:'留空按 1 次'})}${o.team?`<label>团队 / 核心人数<select ${at('team')}>${chooseOptions(Array.from({length:o.team},(_,j)=>[j+1,j===0?'1 人（个人）':(j+1)+' 人']),a.team,'留空按 1 人')}</select></label>`:''}${o.collective?fieldHTML('认定比例（%）',fmtRatio(a.ratio),at('ratio'),{max:100,placeholder:'留空为均分'}):''}${o.type==='discipline'&&project.config.discipline==='interval'?fieldHTML('审批认定扣分',a.approval,at('approval')):''}<label>审核状态<select ${at('status')}>${chooseOptions(['有效','待审核','不计分'],a.status||'有效')}</select></label></div><div class="fields">${fieldHTML('事项名称 / 凭据编号（同一事项用同一名称）',a.event,at('event')+' maxlength="200"',{type:'text',placeholder:'例如：2026 数学竞赛 A 作品'})}${fieldHTML('凭据位置 / 说明',a.note,at('note')+' maxlength="1000"',{type:'text',placeholder:'材料文件名、路径或审核说明'})}</div><div class="award-feedback" aria-live="polite">${a.status==='不计分'?'':awardFeedback(detail,current(),o,i)}</div></div>`;}
function reviewHTML(s){
 const r=result(s);

 return `<section class="panel"><h2>老师核对</h2>${window.ScoreUX?.recentChanges(s)||''}<p class="hint">核对材料和当前计分结果后，登记老师已核对即可。无需先登记学生核对。</p><div id="reviewLive">${r.issues.length?issuesHTML(r.issues):'<div class="note">✓ 成绩齐全，输入校验通过。</div>'}${r.work.length?`<div class="note amber">${r.work.map(i=>`<button class="notice-link" data-locate="${esc(i.id)}">${esc(i.message)} →</button>`).join('')}</div>`:'<div class="note">✓ 材料及资格检查已完成，可以登记老师核对。</div>'}</div><label class="check checkline"><input type="checkbox" data-qualification ${s.qualified?'checked':''}>我已核对学生资格、同一作品取最高奖、跨项 / 跨年度去重及同序列任职取最高。</label><details class="simple-extra" ${s.exception||s.note?'open':''}><summary>特殊情况与备注（没有则不用填）</summary><label class="check checkline"><input type="checkbox" data-exception ${s.exception?'checked':''}>有特殊贡献、取消全部加分等需另行认定的个案。</label><label>老师 / 班委备注<textarea data-student-note rows="2" maxlength="2000">${esc(s.note||'')}</textarea></label></details><div class="flow simple-review-flow"><div class="${r.ready?'done':''}"><b>1. 成绩与材料齐全</b><span class="hint">${r.ready?'已满足老师核对条件':'先处理上面的提示'}</span></div><div class="${r.approved?'done':''}"><b>2. 老师核对完成</b><span class="hint">${r.approved?esc(s.approval.actor+' · '+s.approval.time):'由老师核对后据实登记'}</span></div></div><div class="actions"><button class="primary" data-action="approve" ${r.ready&&!r.approved?'':'disabled'}>${r.approved?'老师已核对':'确认老师已核对'}</button></div><p class="hint">修改成绩、奖项、凭据、资格或规则后，需要老师重新核对。学生核对登记移至“其他功能”，不会阻挡这里。</p></section><details class="panel simple-score-details" open><summary>查看得分构成与计算口径</summary><div class="split"><div>${RULES.dims.filter(d=>d.module==='基本').map(d=>chartHTML(d,r)).join('')}</div><div>${RULES.dims.filter(d=>d.module==='发展').map(d=>chartHTML(d,r)).join('')}</div></div>${r.overflow?`<div class="note">职业大赛溢出 ${fmt(r.overflow)} 分，已转入科学创新；仍受该维度上限约束。</div>`:''}<p class="hint">综合成绩 = 基本 ${fmt(r.basic)} × ${project.config.weights[0]} ＋ 专业 ${fmt(r.professional)} × ${project.config.weights[1]} ＋ 发展 ${fmt(r.development)} × ${project.config.weights[2]}。</p></details>`;
}
function chartHTML(d,r){const value=r.dimensions[d.name];return `<div class="chart-row"><span>${d.name}</span><div class="bar"><i style="width:${Math.min(100,Math.max(0,(value||0)/d.max*100))}%"></i></div><b>${fmt(value)} <small class="hint">/${d.max}</small></b></div>${window.ScoreUX?.dimensionSummary(d,r)||''}`;}
let modalGeneration=0,modalContext=null;
function modal(title,body,foot=''){const d=$('#modal');delete d.dataset.view;modalGeneration++;modalContext={workspace:project.workspaceId,serial:project.serial,student:selected};$('#modalContent').oninput=null;$('#modalContent').innerHTML=`<div class="modal-head"><h2 id="modalHeading" tabindex="-1">${title}</h2><button data-action="closeModal" class="plain" aria-label="关闭">✕</button></div><div class="modal-body">${body}<div id="modalError" class="modal-error" role="alert" tabindex="-1"></div></div><div class="modal-foot">${foot||'<button data-action="closeModal">关闭</button>'}</div>`;d.setAttribute('aria-labelledby','modalHeading');if(!d.open)d.showModal();$('#modalHeading').focus({preventScroll:true});d.scrollTop=0;}
const modalError=m=>{const el=$('#modalError');if(!el)return;el.textContent=m;if(m){el.focus({preventScroll:true});el.scrollIntoView({block:'nearest',behavior:'instant'});}};
function modalUnchanged(student=false){if(!modalContext||modalContext.workspace!==project.workspaceId||modalContext.serial!==project.serial||student&&modalContext.student!==selected){modalError('数据或当前学生已变化，请关闭后重新打开，核对最新内容再确认。');return false;}return true;}
function help(){modal('日常只用这三步',`<ol class="help-list"><li><b>班级总览：</b>在“名单管理”导入学生名单。</li><li><b>数据录入：</b>在“成绩表”填成绩，已有 Excel 数据就整块粘贴；切到“活动与奖项”选项目、等级和次数。这些都是同一份数据，不用重复录入。</li><li><b>老师核对：</b>处理缺失和材料问题后，登记老师已核对，再回总览导出结果。不需要先登记学生核对。</li></ol><div class="note">学生核对是可选功能，单独放在“其他功能”中。<br>数据自动保存在本机；Ctrl+S 可立即保存。换电脑前，在“数据与备份”下载完整 JSON。</div>`);}
function download(name,content,type='application/json;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function fileTime(){return new Date().toISOString().replace(/[:.]/g,'-').slice(0,19);}
function backup(){download('综测完整备份_'+fileTime()+'.json',JSON.stringify(project,null,2));lastBackupSerial=project.serial;toast('已发起下载，请保管好 JSON 备份文件。');}
function csvCell(v){let str=String(v??'');if((/^[\s]*[=+\-@＝＋－＠]/.test(str)||/^[\t\r\n]/.test(str))&&typeof v!=='number')str="'"+str;return '"'+str.replaceAll('"','""')+'"';}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n');}
function exportDialog(){window.ScoreUX.exportDialog();}
function exportCSV(kind){
 if(kind==='ledger')return window.ScoreUX.exportLedger();const source=window.ScoreUX.exportSource();
 let rows;if(kind==='details'){rows=[['学号','姓名','班级','观测点','项目','奖次或认定值','次数','人数','认定比例','状态','事项','凭据说明','单项分']];for(const s of source){const r=result(s);for(const [id,list]of Object.entries(s.awards))for(const [i,a]of list.entries())rows.push([s.id,s.name,s.group,id,ruleMap.get(id).name,a.option,E.blank(a.count)?1:a.count,a.team,a.ratio,awardStateLabel(a,r.details[id]?.[i]),a.event,a.note,r.details[id]?.[i]?.value]);}}
 else{rows=[['学号','姓名','班级','基本素质','专业素质','发展素质','综合成绩','进度','规则状态',...RULES.dims.map(d=>d.name),'问题说明']];for(const s of source){const r=result(s);if(kind==='approved'&&!r.approved)continue;rows.push([s.id,s.name,s.group,r.basic,r.professional,r.development,r.total,r.status,project.config.confirmed?'已确认':'试算',...RULES.dims.map(d=>r.dimensions[d.name]),[...r.issues,...r.work].map(x=>x.message).join('；')]);}}
 if(rows.length===1){toast('没有可导出的记录。');return;}download('综测_'+(kind==='approved'?'已复核':kind==='details'?'奖项明细':'全部试算')+'_'+fileTime()+'.csv',csv(rows),'text/csv;charset=utf-8');toast('已导出 '+(rows.length-1)+' 条记录。');
}
function settings(){const c=project.config;modal('评定规则设置',`<div class="fields">${fieldHTML('工作区名称',project.title,'id="cfgTitle" maxlength="80"',{type:'text'})}${fieldHTML('登记操作人',c.operator,'id="cfgOperator" maxlength="60"',{type:'text',placeholder:'例如：张老师 / 李班委'})}</div><div class="fields">${fieldHTML('评定学年',c.year,'id="cfgYear" maxlength="60"',{type:'text',placeholder:'例如：2027–2028'})}${fieldHTML('适用年级',c.cohort,'id="cfgCohort" maxlength="60"',{type:'text',placeholder:'例如：2027 级'})}</div><div class="fields">${['基本','专业','发展'].map((n,i)=>fieldHTML(n+'素质权重（%）',c.weights[i]*100,`data-weight="${i}"`,{max:100})).join('')}</div><div class="fields">${fieldHTML('同学互评权重（%）',c.peer*100,'id="cfgPeer"')}${fieldHTML('辅导员评议权重（%）',c.counselor*100,'id="cfgCounselor"')}</div><div class="fields"><label>封顶与扣分顺序<select id="cfgOrder">${chooseOptions([['cap','先封顶后扣分'],['deduct','先扣分后封顶']],c.capFirst?'cap':'deduct')}</select></label><label>维度下限<select id="cfgFloor">${chooseOptions([['zero','最低 0 分'],['negative','允许维度负分']],c.floor?'zero':'negative')}</select></label><label>纪律处分口径<select id="cfgDiscipline">${chooseOptions([['fixed','量化参考固定值'],['interval','办法区间认定']],c.discipline)}</select></label></div><label class="check"><input id="cfgConfirmed" type="checkbox" ${c.confirmed?'checked':''}>已由学院确认适用年级、当前计分口径与权重，可按此规则复核。</label><div class="note amber">当前内置量化规则供本地参考，请按实际适用范围确认。未确认时只能试算。更改设置会使原学生核对和老师复核失效。</div>`, '<button data-action="closeModal">取消</button><button class="primary" data-action="saveSettings">保存设置</button>');}
function saveSettings(){try{if(!guard()||!modalUnchanged())return;const old=project.config,c={...old,year:$('#cfgYear').value.trim(),cohort:$('#cfgCohort').value.trim(),operator:$('#cfgOperator').value.trim(),weights:[...document.querySelectorAll('[data-weight]')].map(x=>x.value===''?NaN:Number(x.value)/100),peer:$('#cfgPeer').value===''?NaN:Number($('#cfgPeer').value)/100,counselor:$('#cfgCounselor').value===''?NaN:Number($('#cfgCounselor').value)/100,capFirst:$('#cfgOrder').value==='cap',floor:$('#cfgFloor').value==='zero',discipline:$('#cfgDiscipline').value,confirmed:$('#cfgConfirmed').checked};const errors=E.configErrors(c);if(c.confirmed&&(!c.year||!c.cohort||!c.operator))errors.push('确认规则前，请填写学年、年级和操作人。');if(!$('#cfgTitle').value.trim())errors.push('请填写工作区名称。');if(errors.length)return modalError(errors.join('\n'));const title=$('#cfgTitle').value.trim();mutate('修改规则',()=>{project.title=title;project.config=c;for(const s of project.students){s.confirmation=null;s.approval=null;}},{all:true,student:null});$('#modal').close();toast('设置已保存，按当前规则重新计算。');}catch(e){reportError(e);}}
const requiredColumns=[['专业素质','professional',-1,100],['体测','D024',0,100],['耐力跑','D025',0,100],...RULES.obs.filter(o=>o.type==='base').flatMap(o=>[['互评','辅导员'].map((n,i)=>[o.dim+n,o.id,i,o.max])]).flat()];
function bulk(mode='roster'){
 bulkMode=mode;previewData=null;modal(mode==='roster'?'批量导入 / 更新学生名单':'批量填写必填成绩',`<div class="small-actions"><button data-action="template">下载导入模板</button><button data-action="readCSV">选择 CSV 文件</button></div><p class="hint">${mode==='roster'?'复制三列：学号、姓名、班级。同学号更新姓名 / 班级，不清除原有成绩；新学号追加。':'第一列是学号，后面依次为：'+requiredColumns.map(x=>x[0]).join('、')+'。只填前三项成绩也可以；空白或缺列保持原值，不会清空。'}</p><textarea id="bulkText" rows="7" placeholder="${mode==='roster'?'学号\t姓名\t班级\n20270001\t张同学\t一班':'学号\t专业素质\t体测\t耐力跑\n20270001\t90\t85\t90'}"></textarea><div id="bulkPreview"></div>`, '<button data-action="closeModal">取消</button><button data-action="previewBulk">先检查数据</button><button id="applyBulk" class="primary" data-action="applyBulk" disabled>确认导入</button>');
}
function previewBulk(){try{let rows=E.parseCSV($('#bulkText').value);if(rows[0]&&['学号','学生学号','id'].includes(rows[0][0].toLowerCase()))rows.shift();if(!rows.length)throw Error('请先粘贴数据。');if(rows.length>500)throw Error('一次最多导入 500 行。');const seen=new Set(),existing=new Map(project.students.map(s=>[s.id,s])),errors=[],changes=[];let added=0,updated=0;
 rows.forEach((row,i)=>{const id=row[0]?.trim();if(!id||id.length>120||seen.has(id)){errors.push(`第 ${i+1} 行：学号缺失、过长或重复`);return;}seen.add(id);if(bulkMode==='roster'){if(row.length!==3||!row[1]||!row[2]||row[1].length>120||row[2].length>120){errors.push(`第 ${i+1} 行：须为完整的“学号、姓名、班级”三列`);return;}if(existing.has(id))updated++;else added++;changes.push({id,name:row[1],group:row[2]});}
 else{if(!existing.has(id)){errors.push(`第 ${i+1} 行：学号 ${id} 不在名单中`);return;}if(row.length<2||row.length>requiredColumns.length+1){errors.push(`第 ${i+1} 行：列数不正确，请按模板排列`);return;}const values={};for(let j=1;j<row.length;j++){if(row[j]==='')continue;const n=Number(row[j]),f=requiredColumns[j-1];if(!Number.isFinite(n)||n<0||n>f[3])errors.push(`第 ${i+1} 行“${f[0]}”须为 0–${f[3]} 的数值`);else values[j-1]=n;}if(Object.keys(values).length){changes.push({id,values});updated++;}}
 });if(project.students.length+added>500)errors.push('导入后超过 500 人，请拆分为不同工作区备份。');if(errors.length)throw Error(errors.slice(0,15).join('\n')+(errors.length>15?'\n……':'')+'\n本次未修改任何数据。');if(!changes.length)throw Error('没有需要更新的数据。');previewData={mode:bulkMode,changes,text:$('#bulkText').value,serial:project.serial};$('#bulkPreview').innerHTML=`<div class="note">检查通过：新增 ${added} 人，更新 ${updated} 人。${bulkMode==='grades'?'空白保持原值；真实 0 分会写入。':''}</div><div class="table-wrap preview"><table><thead><tr><th>学号</th><th>${bulkMode==='roster'?'姓名':'更新项数'}</th><th>${bulkMode==='roster'?'班级':'姓名'}</th></tr></thead><tbody>${changes.slice(0,8).map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name||Object.keys(x.values).length)}</td><td>${esc(x.group||existing.get(x.id).name)}</td></tr>`).join('')}</tbody></table></div>`;$('#applyBulk').disabled=false;modalError('');
 }catch(e){previewData=null;$('#applyBulk').disabled=true;$('#bulkPreview').innerHTML='';modalError(e.message);}}
function applyBulk(){if(!previewData||previewData.text!==$('#bulkText').value||previewData.serial!==project.serial)return modalError('数据已变化，请重新检查。');const p=previewData;if(!guard())return;mutate('批量导入',()=>{for(const x of p.changes){let s=project.students.find(s=>s.id===x.id);if(p.mode==='roster'){if(!s){s={id:x.id,name:x.name,group:x.group,professional:null,values:{},awards:{},revision:0,qualified:false,exception:false,note:''};project.students.push(s);}else{s.name=x.name;s.group=x.group;touch(s);}}else{for(const [idx,n]of Object.entries(x.values)){const f=requiredColumns[Number(idx)];if(f[1]==='professional')s.professional=n;else(s.values[f[1]]??=[])[f[2]]=n;}touch(s);}}},{all:true,student:null});window.ScoreUX?.releaseDraft();$('#modal').close();toast('已导入 '+p.changes.length+' 人，自动计算并保存。');}
function template(){const rows=bulkMode==='roster'?[['学号','姓名','班级']]:[['学号',...requiredColumns.map(f=>f[0])],...project.students.map(s=>[s.id,...requiredColumns.map(f=>f[1]==='professional'?s.professional:s.values[f[1]]?.[f[2]])])];download(bulkMode==='roster'?'学生名单模板.csv':'必填成绩模板.csv',csv(rows),'text/csv;charset=utf-8');}
function editStudent(create=false){const s=create?null:current();modal(create?'添加学生':'编辑学生信息',`<div class="fields">${fieldHTML('学号',s?.id||'','id="editId" maxlength="120"',{type:'text'})}${fieldHTML('姓名',s?.name||'','id="editName" maxlength="120"',{type:'text'})}${fieldHTML('班级',s?.group||'','id="editGroup" maxlength="120"',{type:'text'})}</div><p class="hint">修改学号时，当前学生的所有记录一起迁移，不按姓名匹配。</p>${s?'<button class="danger" data-action="deleteStudent">移除这名学生</button>':''}`,`<button data-action="closeModal">取消</button><button class="primary" data-action="saveStudent" data-create="${create}">保存</button>`);}
function saveStudent(create){if(!guard()||!modalUnchanged(true))return;const id=$('#editId').value.trim(),name=$('#editName').value.trim(),group=$('#editGroup').value.trim(),old=create?null:current();if(!id||!name||!group)return modalError('学号、姓名和班级都要填写。');if(project.students.some(s=>s.id===id&&s!==old))return modalError('学号已存在，不能重复。');if(create&&project.students.length>=500)return modalError('已达到 500 人容量。');mutate(create?'添加学生':'编辑学生',()=>{if(create)project.students.push({id,name,group,values:{},awards:{},professional:null,revision:0,qualified:false,exception:false,note:''});else{old.id=id;old.name=name;old.group=group;touch(old);}selected=id;},{all:true,student:null});$('#modal').close();page='students';render();}
function confirmAction(approval){const s=current(),r=result(s);if(!r.ready)return toast('请先处理所有提示。');modal(approval?'确认老师核对':'登记学生核对（可选）',`<p>${esc(s.name)}（${esc(s.id)}）当前试算总分 <b>${fmt(r.total)}</b>。</p><div class="fields">${fieldHTML(approval?'复核老师姓名':'登记人姓名',window.ScoreUX?.actor()||project.config.operator,'id="actor" maxlength="60"',{type:'text'})}</div><label class="check"><input id="humanConfirmed" type="checkbox">${approval?'我已完成材料和计分规则复核，同意按当前结果归档。':'学生已查看个人核对单并确认当前成绩，我据实登记。'}</label><p class="hint">本记录不等同于在线实名签署。数据或规则修改后自动失效。</p>`,`<button data-action="closeModal">取消</button><button class="primary" data-action="recordConfirmation" data-approval="${approval}">确认登记</button>`);}
function recordConfirmation(approval){if(!guard()||!modalUnchanged(true))return;const actor=$('#actor').value.trim();if(!actor||!$('#humanConfirmed').checked)return modalError('请填写登记人姓名，并勾选确认。');const s=current(),r=result(s);if(!r.ready)return modalError('当前数据不满足条件，请重新核对。');window.ScoreUX?.rememberActor(actor);checkpoint('登记确认',s);s[approval?'approval':'confirmation']={revision:s.revision,rules:JSON.stringify(project.config),actor,time:stamp()};recalc(s);modified();$('#modal').close();if(page==='students'&&$('#editor')){renderEditor();renderRoster();}else render();toast('已登记'+(approval?'老师核对':'学生核对（可选）')+'。');}
function printSheets(students){if(!students.length)return;$('#modal').close();$('#printArea').innerHTML=students.map(s=>{const r=result(s);const rows=RULES.obs.filter(o=>{if(['base','external'].includes(o.type))return true;return (s.awards[o.id]?.length||s.values[o.id]?.some(v=>!E.blank(v)))||r.points[o.id]===null;}).map(o=>{let text;if(['award','range','discipline'].includes(o.type))text=(s.awards[o.id]||[]).map((a,i)=>`${a.option||'未选择奖次'} × ${E.blank(a.count)?1:a.count} / ${awardStateLabel(a,r.details[o.id]?.[i])} / ${a.event||'未填写事项'}${a.team?' / '+a.team+'人':''}${!E.blank(a.ratio)?' / 比例'+fmtRatio(a.ratio)+'%':''}${a.approval?' / 认定扣分'+a.approval:''}${a.note?' / '+a.note:''}`).join('；');else text=o.fields.map((f,i)=>f.label+'：'+(s.values[o.id]?.[i]??'未填')).join('，');return `<tr><td>${esc(o.dim+' / '+o.name)}</td><td>${esc(text)}</td><td>${o.sign<0?'−':''}${fmt(r.points[o.id])}</td></tr>`;}).join('');return `<article class="print-sheet"><h1>综合素质评价 · 个人核对单</h1><p>${esc(project.config.year||'学年未设置')} / ${esc(project.config.cohort||'年级未设置')}　${project.config.confirmed?'规则已确认':'规则未确认，仅供试算'}<br><b>${esc(s.name)}</b>　${esc(s.id)}　${esc(s.group)}　进度：${esc(r.status)}</p><p><b>综合成绩 ${fmt(r.total)}</b>　基本 ${fmt(r.basic)} × ${project.config.weights[0]} ＋ 专业 ${fmt(r.professional)} × ${project.config.weights[1]} ＋ 发展 ${fmt(r.development)} × ${project.config.weights[2]}</p><table class="dimtable"><tr>${RULES.dims.map(d=>`<th>${d.name}</th>`).join('')}</tr><tr>${RULES.dims.map(d=>`<td>${fmt(r.dimensions[d.name])}</td>`).join('')}</tr></table><table><thead><tr><th>观测点</th><th>填报内容 / 事项</th><th>分数</th></tr></thead><tbody>${rows}</tbody></table>${r.issues.length||r.work.length?'<p>待处理：'+esc([...r.issues,...r.work].map(i=>i.message).join('；'))+'</p>':''}<p>备注：${esc(s.note||'无')}<br>学生核对（可选）：${esc(r.confirmed?s.confirmation.time:s.confirmation?'原记录已失效':'未登记，不影响老师核对')}　老师核对：${esc(r.approved?s.approval.time:s.approval?'原核对已失效':'未登记')}</p><div class="sig"><span>学生签字（可选）：_______________</span><span>复核人：_______________</span><span>日期：_______________</span></div><p>导出时间：${stamp()} · 保留个人信息，勿公开传播。</p></article>`;}).join('');window.print();}
async function restoreFile(file){try{if(!guard())return;if(file.size>30*1024*1024)throw Error('备份文件超过 30 MB，请检查是否选择正确。');const context={generation:modalGeneration,workspace:project.workspaceId,serial:project.serial,wasOpen:$('#modal').open};const text=await file.text();if(context.wasOpen&&!$('#modal').open||context.generation!==modalGeneration||context.workspace!==project.workspaceId||context.serial!==project.serial)return toast('读取期间页面或数据已变化，本次恢复已取消，请重新选择文件。');const data=E.validateProject(JSON.parse(text),RULES);modal('恢复完整备份',`<p>文件：${esc(file.name)}<br>包含 <b>${data.students.length}</b> 名学生，工作区“${esc(data.title||'未命名')}”。<br>最后更新：${esc(data.modified||'未知')}</p><div class="note amber">恢复会替换当前工作区。当前数据会保留在“撤销上一步”与最近自动存档中；建议先下载当前备份。</div><div class="small-actions"><button data-action="backup">先备份当前数据</button></div><label class="check checkline"><input id="restoreCheck" type="checkbox">确认用此文件替换当前工作区。</label>`,`<button data-action="closeModal">取消</button><button class="primary" id="confirmRestore">恢复这份备份</button>`);$('#confirmRestore').onclick=()=>{if(!guard()||!modalUnchanged())return;if(!$('#restoreCheck').checked)return modalError('请先勾选确认。');mutate('恢复备份',()=>{const serial=project.serial;project=clone(data);project.serial=serial;selected='';},{all:true,student:null});$('#modal').close();toast('完整备份已恢复。');};}catch(e){reportError(e);}}
async function historyDialog(){try{const records=await new Promise((resolve,reject)=>{const t=db.transaction('history','readonly'),r=t.objectStore('history').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const rows=records.filter(r=>r.serial<project.serial).sort((a,b)=>b.serial-a.serial);modal('最近自动存档',`<p class="hint">保留最近 6 次成功保存。恢复存档会替换当前工作区，请先备份。</p>${rows.map((r,i)=>`<div class="toolbar"><span>${esc(r.time)} · ${r.data.students.length} 人</span><button data-history="${i}">恢复这一版</button></div>`).join('')||'<p>暂无更早存档。</p>'}<button data-action="backup">备份当前数据</button>`);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const r=rows[Number(b.dataset.history)];modal('确认恢复存档',`<p>将恢复 ${esc(r.time)} 的 ${r.data.students.length} 人数据。</p><div class="note amber">当前数据将被替换，仍可立即撤销。</div>`,'<button data-action="closeModal">取消</button><button class="primary" id="applyHistory">确认恢复</button>');$('#applyHistory').onclick=()=>{mutate('恢复自动存档',()=>{const serial=project.serial;project=clone(r.data);project.serial=serial;selected='';},{all:true,student:null});$('#modal').close();};});}catch(e){reportError(e);}}
async function performanceDialog(){modal('500 人性能检查',`<p>使用独立的模拟数据，不修改现有学生。测量批量计分、检索、本机数据库写入与读回。</p><button class="primary" id="runPerf">开始检查</button><pre id="perfResult"></pre>`);$('#runPerf').onclick=async()=>{const button=$('#runPerf');button.disabled=true;$('#perfResult').textContent='正在测量…';await new Promise(r=>setTimeout(r,30));try{const r=await perfTest();$('#perfResult').textContent=JSON.stringify(r,null,2);}catch(e){$('#perfResult').textContent=e.message;}button.disabled=false;};}
async function perfTest(){const students=Array.from({length:500},(_,i)=>{const s=clone(SAMPLES[i%SAMPLES.length]);s.id='PERF'+String(i).padStart(4,'0');s.name='模拟学生'+i;for(const o of RULES.obs){if(o.type==='qty')s.values[o.id]=[20];if(o.type==='activity')s.values[o.id]=o.audience?[2,4,8,1,2,4]:o.cap===null?[2,4]:[2,4,8];if(o.type==='bool')s.values[o.id]=['是'];if(['award','range'].includes(o.type))s.awards[o.id]=Array.from({length:3},(_,j)=>({option:o.options[j%o.options.length][0],count:1,team:3,status:'有效',event:o.id+'-'+j}));}return s;});let t=performance.now();const scores=students.map(s=>E.calculate(s,project.config,RULES));const compute=performance.now()-t;t=performance.now();for(let i=0;i<100;i++)students.filter(s=>s.name.includes('25')||s.id.includes('25'));const search=performance.now()-t;const p={...project,students};t=performance.now();await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(p,'performance-only');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});const write=performance.now()-t;t=performance.now();const saved=await readStore('workspace','performance-only'),read=performance.now()-t;await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').delete('performance-only');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});if(saved.students.length!==500||scores.length!==500)throw Error('校验未通过');return {学生人数:500,观测点:RULES.obs.length,奖项记录数:students.reduce((n,s)=>n+Object.values(s.awards).reduce((a,v)=>a+v.length,0),0),'500人完整计算_ms':+compute.toFixed(1),'100次检索_ms':+search.toFixed(1),'本机写入_ms':+write.toFixed(1),'本机读回_ms':+read.toFixed(1),'JSON数据_KB':Math.round(JSON.stringify(p).length/1024),读回校验:'通过',说明:'当前电脑当前浏览器单次测量，时间会随设备和数据量变化；未改动正式工作区'};}
function locate(id){if(id==='config')return settings();if(id==='identity')return editStudent();if(['qualification','exception'].includes(id)){tab='review';renderEditor();return;}if(id==='professional'||['base','external'].includes(ruleMap.get(id)?.type)){tab='required';renderEditor();const input=id==='professional'?$('[data-professional]'):$(`[data-value="${id}"]`);input?.focus();return;}if(ruleMap.has(id)){tab='activities';dimension=ruleMap.get(id).dim;renderEditor();const obs=$('#obs-'+id);if(obs){obs.hidden=false;obs.open=true;const only=$('#onlyFilled');if(only)only.checked=false;document.querySelectorAll('.observation').forEach(e=>e.hidden=false);$('#observationMatches').textContent='';const input=obs.querySelector('input,select,[data-add-award]');input?.focus({preventScroll:true});obs.querySelector('summary').scrollIntoView({block:'nearest',behavior:'instant'});obs.classList.add('located');setTimeout(()=>obs.classList.remove('located'),1200);window.ScoreEntry?.remember();window.ScoreUX?.decorate();}}}
