 $('#modalContent').oninput=invalidate;
 $('#previewBatchAward').onclick=()=>{try{
  const o=ruleMap.get($('#batchObservation').value);if(!o)throw Error('请选择观测点。');
  const a={option:$('#batchOption').value,count:Number($('#batchCount').value),status:$('#batchStatus').value,event:$('#batchEvent').value.trim(),note:$('#batchNote').value.trim()};if(o.team)a.team=Number($('#batchTeam').value);if(o.collective)a.ratio=$('#batchRatio').value===''?'':Number($('#batchRatio').value)/100;
  if(!a.option||!a.event||!Number.isInteger(a.count)||a.count<1)throw Error('请选择奖次，填写事项名称及大于 0 的整数次数。');
  let ids=E.parseCSV($('#batchIds').value).map(r=>r[0]);if(['学号','学生学号','id'].includes(ids[0]?.toLowerCase()))ids.shift();if(!ids.length||ids.length>500||new Set(ids).size!==ids.length)throw Error('学号不能为空、不能重复，每次最多 500 人。');
  const students=new Map(project.students.map(s=>[s.id,s])),errs=[];
  for(const id of ids){const s=students.get(id);if(!s){errs.push(id+' 不在学生名单中');continue;}if(Object.values(s.awards).flat().some(x=>x.event?.trim()===a.event&&x.status!=='不计分'))errs.push(s.name+'（'+s.id+'）已有同一事项记录，请先核对，避免重复');if((s.awards[o.id]?.length||0)>=1000||Object.values(s.awards).reduce((n,v)=>n+v.length,0)>=5000)errs.push(s.name+' 的记录已达上限');}
  const sample={id:'检验',name:'检验',group:'检验',professional:0,values:{},awards:{[o.id]:[{...a,status:'有效'}]},revision:0};const trial=E.calculate(sample,project.config,RULES);for(const e of trial.issues.filter(i=>i.id===o.id))errs.push(e.message);
  if(errs.length)throw Error(errs.slice(0,8).join('\n')+'\n本次尚未修改任何数据。');preview={ids,o:o.id,a,serial:project.serial};$('#batchAwardPreview').innerHTML=`<div class="note">检查通过：${ids.length} 人，每人追加 ${esc(a.option)} × ${a.count}，审核有效后的原始个人参考贡献 ${fmt(trial.points[o.id])} 分，当前状态“${esc(a.status)}”。${a.status==='待审核'?'本次新增记录暂不计分，需人工审核后才计分。':'最终分数仍受维度封顶与扣分约束。'}${o.team&&ids.length>1&&a.team===1?' 当前填写为 1 人项目；名单人数不等于团队人数，请核实团队人数后再确认。':''}</div><p class="hint">${ids.slice(0,12).map(id=>esc(students.get(id).name)).join('、')}${ids.length>12?'……':''}</p>`;$('#applyBatchAward').disabled=false;modalError('');
 }catch(e){invalidate();modalError(e.message);}};
 $('#applyBatchAward').onclick=()=>{if(!guard())return;if(!preview||preview.serial!==project.serial)return modalError('数据已变化，请重新检查。');const data=preview;mutate('批量登记同一奖项',()=>{const map=new Map(project.students.map(s=>[s.id,s]));for(const id of data.ids){const s=map.get(id);(s.awards[data.o]??=[]).push(clone(data.a));touch(s);}},{all:true,student:null});window.ScoreUX?.releaseDraft();$('#modal').close();toast('已为 '+data.ids.length+' 位学生登记奖项。');};
