function awardStateLabel(a,d){return a.status==='不计分'?'不计分':d?.errors?.length?'输入需更正':d?.missing?.length?'待填写':a.status||'有效';}
function awardCaption(a,i,d){return `记录 ${i+1} · ${a.status==='不计分'?'已排除':d?.errors?.length?'需更正':d?.missing?.length?'待填写（暂不计分）':fmt(d?.value)+' 分'}${a.status==='待审核'?'（待审核，暂不计入）':''}`;}
function awardFeedback(d,s=current(),o=null,i=-1){return (window.ScoreUX?.awardHints(s,o,i)||'')+ `${d?.missing?.length?'<div class="hint award-incomplete">待填写：'+esc(d.missing.join('；'))+'。可以接着填写，未完成前不能确认复核。</div>':''}${d?.errors?.length?'<div class="modal-error">'+esc(d.errors.join('；'))+'</div>':''}`;}
function updateObsFeedback(s,o,el,updateDimensions=true){
 if(!el)return;const r=result(s),feedback=el.querySelector('.obs-feedback');
 if(feedback){const html=r.issues.filter(i=>i.id===o.id).map(i=>`<div class="note red">${esc(i.message)}</div>`).join('')+(o.type==='job'?r.work.filter(i=>i.id===o.id).map(i=>`<div class="hint award-incomplete">${esc(i.message)}</div>`).join(''):'');if(feedback.innerHTML!==html)feedback.innerHTML=html;}
 el.dataset.filled=String((s.values[o.id]||[]).some(v=>!E.blank(v))||(s.awards[o.id]||[]).length>0);
 const strong=el.querySelector('.obs-head strong');if(strong)strong.textContent=r.points[o.id]===null?'待处理':(o.sign<0?'−':'')+fmt(r.points[o.id]);
 const status=el.querySelector('[data-observation-status]');if(status){const ds=r.details[o.id]||[];status.innerHTML=ds.some(d=>d.missing?.length&&d.status!=='不计分')?'<span class="badge amber">待填写</span>':(s.awards[o.id]||[]).some(a=>a.status==='待审核')?'<span class="badge amber">待审核</span>':'';}
 el.querySelectorAll('[data-record-value]').forEach(span=>{const i=Number(span.dataset.recordValue),d=r.details[o.id]?.[i],a=s.awards[o.id][i],caption=awardCaption(a,i,d);if(span.textContent!==caption)span.textContent=caption;const feedback=span.closest('.award-row').querySelector('.award-feedback');if(feedback){const html=a.status==='不计分'?'':awardFeedback(d,s,o,i);if(feedback.innerHTML!==html)feedback.innerHTML=html;}});
 if(updateDimensions)document.querySelectorAll('[data-dimension]').forEach(b=>{const d=b.dataset.dimension,html=esc(d)+' <small>'+fmt(r.dimensions[d])+'</small>';if(b.innerHTML!==html)b.innerHTML=html;});
}
function refreshActivitySummary(s,o,el){$('#scoreStrip').innerHTML=stripHTML(s);$('#scoreStrip .total')?.insertAdjacentHTML('beforeend','<button class="linkish compact" data-explain="total">查看计算过程</button>');$('#studentBadge').innerHTML=badge(result(s).status);renderRoster();updateObsFeedback(s,o,el);document.querySelectorAll('.footer-actions [data-action=undo]').forEach(b=>b.disabled=!undoStack.length);}
// Keep existing fields (and their focus/Tab order) alive. Only the added/removed row changes.
function changeAwardRows(id,removeIndex=null){
 if(!guard())return;const s=current(),o=ruleMap.get(id),el=$('#obs-'+id),editor=$('#editor'),button=el?.querySelector('[data-add-award]');if(!s||!o||!button)return;
 const scroll={editor:editor.scrollTop,x:scrollX,y:scrollY};let focus;
 if(removeIndex===null){const i=(s.awards[id]||[]).length;mutate('添加奖项',()=>{(s.awards[id]??=[]).push({option:'',count:1,team:1,event:'',note:'',status:'有效'});},{refresh:false});button.insertAdjacentHTML('beforebegin',awardHTML(o,s.awards[id][i],i,result(s).details[id]?.[i]));focus=el.querySelector(`[data-award="${id}"][data-row="${i}"][data-key="option"]`);}
 else{const rows=[...el.querySelectorAll('.award-row')];if(!rows[removeIndex])return;mutate('移除奖项',()=>s.awards[id].splice(removeIndex,1),{refresh:false});rows[removeIndex].remove();el.querySelectorAll('.award-row').forEach((row,i)=>{row.querySelectorAll('[data-row]').forEach(f=>f.dataset.row=i);row.querySelector('[data-record-value]').dataset.recordValue=i;});const remaining=el.querySelectorAll('.award-row');focus=remaining[Math.min(removeIndex,remaining.length-1)]?.querySelector('[data-key="option"]')||button;}
 el.open=true;refreshActivitySummary(s,o,el);window.ScoreUX?.decorate();editor.scrollTop=scroll.editor;window.scrollTo(scroll.x,scroll.y);focus?.focus({preventScroll:true});
 if(focus){const rect=focus.getBoundingClientRect(),bounds=editor.getBoundingClientRect(),nested=getComputedStyle(editor).overflowY==='auto',top=nested?Math.max(0,bounds.top):0,bottom=nested?Math.min(innerHeight,bounds.bottom):innerHeight;if(rect.top<top+12||rect.bottom>bottom-12)focus.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});}
}
function handleEdit(target){const s=current();if(!s||!guard())return;
 if(target.hasAttribute('data-professional'))mutate('修改专业成绩',()=>s.professional=target.value===''?null:Number(target.value),{refresh:false});
 else if(target.dataset.value){const o=ruleMap.get(target.dataset.value),i=Number(target.dataset.index),f=o.fields[i];mutate('修改观测点',()=>{(s.values[o.id]??=[])[i]=target.value===''?'':(['num','count','team','ratio'].includes(f.kind)?Number(target.value):target.value);if(o.type==='job'&&i===0&&target.value===''){s.values[o.id][1]='';const term=$('[data-value="'+o.id+'"][data-index="1"]');if(term)term.value='';}},{refresh:false});}
 else if(target.dataset.award){const a=s.awards[target.dataset.award]?.[Number(target.dataset.row)],key=target.dataset.key;if(!a)return;mutate('修改奖项',()=>{a[key]=target.value===''?'':['count','team','ratio','approval'].includes(key)?Number(target.value)/(key==='ratio'?100:1):target.value;},{refresh:false});}
 else if(target.hasAttribute('data-qualification')){mutate('资格去重核对',()=>s.qualified=target.checked,{refresh:false});}
 else if(target.hasAttribute('data-exception')){mutate('标记个案',()=>s.exception=target.checked,{refresh:false});}
 else if(target.hasAttribute('data-student-note')){mutate('修改备注',()=>s.note=target.value,{refresh:false});$('#studentBadge').innerHTML=badge(result(s).status);renderRoster();return;}
 else return;
 window.ScoreUX?.afterEdit(target);
 // Update feedback in place, including select changes: do not destroy focus or scroll context.
 if(tab==='activities'){const o=ruleMap.get(target.dataset.award||target.dataset.value);refreshActivitySummary(s,o,$('#obs-'+o.id));}
 else{$('#scoreStrip').innerHTML=stripHTML(s);$('#studentBadge').innerHTML=badge(result(s).status);renderRoster();if(tab==='required')$('#requiredIssues').innerHTML=issuesHTML(result(s).issues.filter(i=>['professional',...RULES.obs.filter(o=>['base','external'].includes(o.type)).map(o=>o.id)].includes(i.id)));}
}
document.addEventListener('input',event=>{const target=event.target;if(target.id==='search'){query=target.value;overviewPage=0;rosterPage=0;clearTimeout(renderTimer);renderTimer=setTimeout(()=>page==='overview'?renderOverviewTable():renderRoster(),80);return;}if(target.id==='observationSearch'){const term=target.value.trim().toLowerCase();$('#observationMatches').innerHTML=term?RULES.obs.filter(o=>(o.name+o.dim+o.id).toLowerCase().includes(term)).slice(0,12).map(o=>`<button data-locate="${o.id}">${o.dim} / ${o.name}</button>`).join('')||'<span class="hint">未找到项目，试试其他关键词。</span>':'';return;}if(target.id==='bulkText'){previewData=null;$('#applyBulk').disabled=true;}if(target.matches('input[type=number][data-value],input[data-professional],input[type=number][data-award]'))handleEdit(target);});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='statusFilter'){filter=t.value||'all';overviewPage=rosterPage=0;page==='overview'?renderOverviewTable():renderRoster();return;}if(t.id==='onlyFilled'){document.querySelectorAll('.observation').forEach(d=>d.hidden=t.checked&&d.dataset.filled!=='true');return;}if(t.type==='number'&&(t.dataset.value||t.dataset.award||t.hasAttribute('data-professional')))return;handleEdit(t);});
document.addEventListener('click',async event=>{const target=event.target.closest('button,[data-student],.brand');if(!target)return;if(!initialized&&!['help','closeModal'].includes(target.dataset.action)&&target.id!=='recoverRaw'){toast('正在读取本机数据，请稍候。');return;}try{
 if(target.classList.contains('brand')){event.preventDefault();page='overview';render();return;}
 if(target.dataset.page){page=target.dataset.page;render();return;}
 if(target.dataset.student){selected=target.dataset.student;page='students';render();return;}
 if(target.dataset.tab){tab=target.dataset.tab;renderEditor();return;}
 if(target.dataset.activityModule){dimension=RULES.dims.find(d=>d.module===target.dataset.activityModule).name;renderEditor();return;}if(target.dataset.dimension){dimension=target.dataset.dimension;renderEditor();return;}
 if(target.dataset.locate){locate(target.dataset.locate);return;}
 if(target.dataset.addAward){const id=target.dataset.addAward;if((current().awards[id]?.length||0)>=1000||Object.values(current().awards).reduce((a,v)=>a+v.length,0)>=5000){toast('当前学生记录已达上限，请核对是否重复录入。');return;}changeAwardRows(id);return;}
 if(target.dataset.deleteAward){changeAwardRows(target.dataset.deleteAward,Number(target.dataset.row));return;}
 const a=target.dataset.action;if(!a)return;
 switch(a){
 case 'help':help();break;case 'closeModal':$('#modal').close();break;case 'backup':backup();break;case 'restore':$('#fileInput').value='';$('#fileInput').click();break;
 case 'batchAwards':batchAwards();break;case 'newWorkspace':newWorkspace();break;case 'settings':settings();break;case 'saveSettings':saveSettings();break;case 'bulk':bulk();break;case 'grades':bulk('grades');break;case 'template':template();break;case 'previewBulk':previewBulk();break;case 'applyBulk':applyBulk();break;
 case 'readCSV':$('#csvInput').value='';$('#csvInput').click();break;
 case 'export':exportDialog();break;case 'exportAll':exportCSV('all');break;case 'exportApproved':exportCSV('approved');break;case 'exportDetails':exportCSV('details');break;case 'exportLedger':exportCSV('ledger');break;
 case 'printOne':printSheets([current()]);break;case 'printAll':window.ScoreUX.printRange();break;
 case 'demo':if(!guard())break;mutate('加载示例',()=>{project.students=clone(SAMPLES);project.title='示例班级 · 10 个典型场景';},{all:true,student:null});toast('示例已载入；这些都是虚构数据，可直接尝试。');break;
 case 'toActivities':tab='activities';renderEditor();break;case 'toReview':tab='review';renderEditor();break;
 case 'nextStudent':{const rows=selectedList(),i=rows.findIndex(s=>s.id===selected),next=rows[i+1];if(next){selected=next.id;rosterPage=Math.floor((i+1)/60);renderWorkspace();}else toast('已经是当前筛选中的最后一位。');break;}
 case 'prevTable':overviewPage--;renderOverviewTable();break;case 'nextTable':overviewPage++;renderOverviewTable();break;case 'prevRoster':rosterPage--;renderRoster();break;case 'nextRoster':rosterPage++;renderRoster();break;
 case 'newStudent':editStudent(true);break;case 'editStudent':editStudent();break;case 'saveStudent':saveStudent(target.dataset.create==='true');break;
 case 'deleteStudent':{const s=current();modal('确认移除学生',`<p>移除 ${esc(s.name)}（${esc(s.id)}）及全部关联记录？移除后可以立即撤销。</p>`,`<button data-action="closeModal">取消</button><button class="danger" id="confirmDelete">确认移除</button>`);$('#confirmDelete').onclick=()=>{if(!guard()||!modalUnchanged(true))return;mutate('移除学生',()=>{project.students=project.students.filter(x=>x!==s);selected='';},{all:true,student:null});$('#modal').close();};break;}
 case 'confirmStudent':confirmAction(false);break;case 'approve':confirmAction(true);break;case 'recordConfirmation':recordConfirmation(target.dataset.approval==='true');break;
 case 'undo':undoLastChange();break;
 case 'sortId':case 'sortName':case 'sortScore':case 'sortDefault':viewSort=({sortId:'id',sortName:'name',sortScore:'score',sortDefault:'default'})[a];overviewPage=rosterPage=0;render();break;

 case 'history':await historyDialog();break;case 'performance':await performanceDialog();break;
 }
 }catch(e){reportError(e);}});
$('#fileInput').onchange=()=>{const f=$('#fileInput').files[0];if(f)void restoreFile(f);};
$('#csvInput').onchange=async()=>{const target=$('#bulkText'),generation=modalGeneration,workspace=project.workspaceId;const active=()=>target?.isConnected&&$('#modal').open&&generation===modalGeneration&&workspace===project.workspaceId;try{const f=$('#csvInput').files[0];if(!f||!active())return;if(f.size>5*1024*1024)throw Error('CSV 过大，请检查文件。');const buffer=await f.arrayBuffer();if(!active())return;const text=new TextDecoder('utf-8',{fatal:true}).decode(buffer);target.value=text;target.dispatchEvent(new Event('input',{bubbles:true}));previewBulk();}catch(e){if(active())modalError(e instanceof TypeError?'文件不是 UTF-8 编码，请用“CSV UTF-8”另存，或直接复制粘贴。':e.message);}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='数据尚未保存';}});
