async function boot(){try{
 if(navigator.locks){await new Promise(resolve=>{navigator.locks.request('bupt-standalone-writer',{ifAvailable:true},async lock=>{if(!lock)readOnly=true;resolve();if(lock)await new Promise(r=>releaseLock=r);}).catch(()=>{readOnly=true;resolve();});});}
 db=await openDB();const stored=await readStore('workspace','current');rawStored=stored;if(stored)project=E.validateProject(stored,RULES);recalcAll();initialized=true;saveLabel(readOnly?'只读 · 另一个窗口正在编辑':'✓ 已保存到本机',readOnly);render();if(readOnly)toast('当前为只读窗口。请关闭另一个编辑窗口，再重新打开。');
 }catch(e){loadFailure=true;saveLabel('本机数据打开失败',true);$('#app').innerHTML=`<main><div class="panel"><h1>本机数据未能打开</h1><p>${esc(e.message)}</p><p>请用 Edge / Chrome 普通窗口重新打开。如果已有 JSON 备份，请先保留原文件。应用未覆盖原有数据。</p>${rawStored?'<button id="recoverRaw">导出原始存储记录（供恢复）</button>':''}</div></main>`;if(rawStored)$('#recoverRaw').onclick=()=>download('综测原始存储_'+fileTime()+'.json',JSON.stringify(rawStored,null,2));console.error(e);}}
// Bounded, local diagnostic surface for repeatable tests. No network or privileged operations.
window.ScoreApp={ready:()=>initialized&&!loadFailure,getProject:()=>clone(project),calculate:s=>E.calculate(s,project.config,RULES),perfTest,settled,loadForTest:async p=>{E.validateProject(p,RULES);if(!guard())throw Error('只读');project=clone(p);recalcAll();modified();render();await settled();},renderTimings:()=>{const before=page;page='overview';let t=performance.now();render();const overview=performance.now()-t;page='students';t=performance.now();render();const student=performance.now()-t;page=before;render();return {overview,student};}};
